using System;using System.IO;using System.Text;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using System.Net;using System.Security.Cryptography;using System.Text.RegularExpressions;using System.Threading;using System.Windows.Forms;using System.Windows.Automation;using System.Web.Script.Serialization;
class Collector {
 static readonly string Root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"TomKiClaudeCollector");
 static readonly string Origin="https://macmini.tail25505f.ts.net:8443";
 static JavaScriptSerializer Json=new JavaScriptSerializer();
 static Regex Work=new Regex(@"검측|타설|철근|거푸집|콘크리트|시공|공무|품질|공정표|작업일보|업무일지|자재|기성금|공사비|준공|시방서|설계변경|도면|현장.{0,15}(업무|공사|작업)|업무.{0,15}(자동화|기록|공유|보고)|AI.{0,15}업무|업무.{0,15}AI|LNG TANK|DUCT BANK|U-DITCH",RegexOptions.IgnoreCase);
 static Regex Private=new Regex(@"학번|학업|레포트|과제|교수|취미|여행|주식|투자|비밀번호|패스워드|password|api[_ -]?key|access[_ -]?token|Bearer\s|GOCSPX-|sk-[A-Za-z0-9]|BEGIN .*PRIVATE KEY|연결.{0,5}키",RegexOptions.IgnoreCase);
 static string Hash(string value){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(Encoding.UTF8.GetBytes(value))).Replace("-","").ToLowerInvariant();}
 static byte[] Protect(string value){return ProtectedData.Protect(Encoding.UTF8.GetBytes(value),null,DataProtectionScope.CurrentUser);}
 static string Unprotect(byte[] data){return Encoding.UTF8.GetString(ProtectedData.Unprotect(data,null,DataProtectionScope.CurrentUser));}
 static string Post(string path,string token,string body){var req=(HttpWebRequest)WebRequest.Create(Origin+path);req.Method="POST";req.ContentType="application/json";req.Timeout=15000;req.ReadWriteTimeout=15000;req.AllowAutoRedirect=false;if(!String.IsNullOrEmpty(token))req.Headers["Authorization"]="Bearer "+token;byte[] data=Encoding.UTF8.GetBytes(body);req.ContentLength=data.Length;using(var stream=req.GetRequestStream())stream.Write(data,0,data.Length);using(var response=req.GetResponse())using(var reader=new StreamReader(response.GetResponseStream()))return reader.ReadToEnd();}
 [STAThread]static void Main(string[] args){ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;Directory.CreateDirectory(Root);if(args.Contains("--collect")){Run();return;}if(args.Contains("--self-test")){SelfTest();return;}Install();}
 static void Install(){Application.EnableVisualStyles();var form=new Form{Text="TomKi · Claude 업무 자동 기록 연결",Width=660,Height=460,StartPosition=FormStartPosition.CenterScreen};var help=new Label{Left=24,Top=20,Width=600,Height=205,Text="평소 쓰는 Claude 앱에서 현재 표시된 업무 문단을 자동으로 기록합니다.\n\n사람이 할 일은 Google 로그인과 ‘이 PC 연결’ 승인 한 번입니다.\n기기 키 복사와 수동 설정 없이 설치 프로그램이 연결을 마칩니다.\n\n수집 범위: 현재 대화 본문의 업무 문단만. 사이드바·입력 중 초안은 제외.\n닫힌 앱·최소화·보이지 않는 과거 대화·첨부파일은 수집하지 못합니다.\n앱 버전에 따라 본문을 못 읽으면 전송하지 않습니다. 별도 AI API 호출 없음.\n\n연결 후 실제 업무 대화가 사이트에 들어오는지 확인해야 합니다."};var startup=new CheckBox{Left=24,Top=230,Width=590,Checked=true,Text="Windows 로그인 시 자동 시작 · 트레이에서 중지/해제 가능"};var connect=new Button{Left=24,Top=275,Width=590,Height=45,Text="Google로 연결하고 자동 설치"};var message=new Label{Left=24,Top=335,Width=590,Height=70};connect.Click+=(s,e)=>{connect.Enabled=false;message.Text="Google 연결 화면을 여는 중…";bool startOnLogin=startup.Checked;var worker=new System.ComponentModel.BackgroundWorker();worker.DoWork+=(sender,eventArgs)=>{var pair=Json.Deserialize<Dictionary<string,object>>(Post("/api/collector/pair/start","",Json.Serialize(new{name=Environment.MachineName})));string ident=(string)pair["request_id"],verifier=(string)pair["verifier"];Process.Start(new ProcessStartInfo((string)pair["verification_url"]){UseShellExecute=true});for(int attempt=0;attempt<200;attempt++){Thread.Sleep(3000);var check=Json.Deserialize<Dictionary<string,object>>(Post("/api/collector/pair/poll","",Json.Serialize(new{request_id=ident,verifier=verifier})));if((string)check["state"]!="approved")continue;string token=(string)check["token"];Post("/api/collector/heartbeat",token,"{}");string dest=Path.Combine(Root,"TomKiClaudeCollector.exe");if(!String.Equals(Application.ExecutablePath,dest,StringComparison.OrdinalIgnoreCase))File.Copy(Application.ExecutablePath,dest,true);File.WriteAllBytes(Path.Combine(Root,"device.dat"),Protect(token));string start=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Startup),"TomKiClaudeCollector.cmd");if(startOnLogin)File.WriteAllText(start,"@echo off\r\nstart \"\" \""+dest+"\" --collect\r\n",Encoding.Default);Process.Start(new ProcessStartInfo(dest,"--collect"){UseShellExecute=false});eventArgs.Result="연결·설치 완료. 트레이에서 상태와 중지를 확인하세요.\nClaude 업무 대화를 열고 사이트에 들어오는지 확인해 주세요.";return;}throw new Exception("Google 연결 승인이 만료되었습니다.");};worker.RunWorkerCompleted+=(sender,eventArgs)=>{if(eventArgs.Error!=null){message.Text="연결하지 못했습니다. 인터넷 및 승인 화면을 확인한 뒤 다시 시도하세요.";connect.Enabled=true;}else message.Text=(string)eventArgs.Result;};worker.RunWorkerAsync();message.Text="브라우저에서 Google 로그인 → 이 PC 연결을 승인하세요.\n이 창은 연결을 마칠 때까지 열어 두세요.";};form.Controls.AddRange(new Control[]{help,startup,connect,message});Application.Run(form);}
 static List<string> Capture(){var result=new List<string>();foreach(var process in Process.GetProcessesByName("Claude")){try{if(process.MainWindowHandle==IntPtr.Zero)continue;var window=AutomationElement.FromHandle(process.MainWindowHandle);if(window.Current.IsOffscreen)continue;AutomationElement main=null;var all=window.FindAll(TreeScope.Descendants,Condition.TrueCondition);foreach(AutomationElement element in all){string name=element.Current.Name??"";object role=element.GetCurrentPropertyValue(AutomationProperty.LookupById(30101),true);if((role is string && ((string)role).Split(' ').Contains("main"))||Regex.IsMatch(name,@"^(기본 창|Main window|Main content|Main view)$",RegexOptions.IgnoreCase)){main=element;break;}}if(main==null)continue;var nodes=main.FindAll(TreeScope.Descendants,new PropertyCondition(AutomationElement.ControlTypeProperty,ControlType.Text));foreach(AutomationElement node in nodes){if(node.Current.IsOffscreen)continue;string text=node.Current.Name??"";foreach(string raw in Regex.Split(text,@"\r?\n\s*\r?\n")){string p=raw.Trim();if(p.Length<3||p.Length>3500||!Work.IsMatch(p)||Private.IsMatch(p))continue;p=Regex.Replace(p,@"[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}","[이메일 생략]");p=Regex.Replace(p,@"(?<!\d)01[016789][- ]?\d{3,4}[- ]?\d{4}(?!\d)","[전화번호 생략]");if(!result.Contains(p)&&result.Sum(x=>x.Length)+p.Length<=60000)result.Add(p);if(result.Count>=100)return result;}}}catch(ElementNotAvailableException){}catch(InvalidOperationException){}}return result;}
 static void Run(){bool created;using(var mutex=new Mutex(true,"Local\\TomKiClaudeCollector",out created)){if(!created)return;string token;try{token=Unprotect(File.ReadAllBytes(Path.Combine(Root,"device.dat")));}catch{return;}Directory.CreateDirectory(Path.Combine(Root,"queue"));var tray=new NotifyIcon{Icon=System.Drawing.SystemIcons.Information,Visible=true,Text="Claude 업무 자동 기록 · 시작 중"};var menu=new ContextMenuStrip();bool paused=false,busy=false;var pause=menu.Items.Add("수집 일시 중지");pause.Click+=(s,e)=>{paused=!paused;pause.Text=paused?"수집 다시 시작":"수집 일시 중지";};menu.Items.Add("상태 파일 열기",null,(s,e)=>Process.Start(new ProcessStartInfo("notepad.exe","\""+Path.Combine(Root,"status.txt")+"\""){UseShellExecute=true}));menu.Items.Add("자동 시작 해제",null,(s,e)=>{string path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Startup),"TomKiClaudeCollector.cmd");if(File.Exists(path))File.Delete(path);});menu.Items.Add("종료",null,(s,e)=>Application.Exit());tray.ContextMenuStrip=menu;string previous="",sent="";var timer=new System.Windows.Forms.Timer{Interval=30000};timer.Tick+=(s,e)=>{if(paused||busy)return;busy=true;try{var paragraphs=Capture();string signature=Hash(String.Join("\n\n",paragraphs));if(paragraphs.Count>0&&signature==previous&&signature!=sent){var body=Json.Serialize(new{scope="active-conversation-work-excerpts",snapshot_id=signature,paragraphs=paragraphs});string path=Path.Combine(Root,"queue",signature+".dat");if(Directory.GetFiles(Path.Combine(Root,"queue")).Length<100){File.WriteAllBytes(path,Protect(body));sent=signature;}}previous=signature;int uploaded=0;foreach(var path in Directory.GetFiles(Path.Combine(Root,"queue"),"*.dat").Take(5)){try{Post("/api/collector/ingest",token,Unprotect(File.ReadAllBytes(path)));File.Delete(path);uploaded++;}catch{break;}}string state=DateTime.Now.ToString("s")+" · 현재 업무 문단 "+paragraphs.Count+" · 이번 전송 "+uploaded+" · 대기 "+Directory.GetFiles(Path.Combine(Root,"queue")).Length+"\r\n현재 본문 일부만 수집. 미표시 대화·첨부파일은 포함하지 않습니다.";File.WriteAllText(Path.Combine(Root,"status.txt"),state,Encoding.UTF8);tray.Text=paragraphs.Count>0?"Claude 업무 기록 · 본문 확인 중":"Claude 업무 기록 · 본문/업무 대기";}catch{File.WriteAllText(Path.Combine(Root,"status.txt"),"본문 접근 실패 · 전체 화면 수집으로 대체하지 않습니다.");}finally{busy=false;}};timer.Start();Application.Run();tray.Dispose();}}
 static void SelfTest(){string value="검측 시험용 보호 데이터";if(Unprotect(Protect(value))!=value)throw new Exception("DPAPI failed");if(!Work.IsMatch("검측서 사진 반영")||Work.IsMatch("여행 일정")||!Private.IsMatch("검측 password secret"))throw new Exception("Filter failed");Console.WriteLine("DPAPI and local filter self-test passed. UI capture not exercised.");}
}
